\title{The Algebraic Geometry of Neural Decision Boundaries:\\ A Tropical Framework}
\author{Aristotle}
\date{2026-07-10}

\begin{document}
\maketitle

\begin{abstract}
A feed-forward neural network with rectified-linear (ReLU) activations computes a
piecewise linear function $f : \R^n \to \R^m$. For a binary classifier
$f : \R^n \to \R$, the decision boundary $\{x : f(x) = 0\}$ is a piecewise linear
hypersurface. We show that this boundary is precisely a \emph{tropical hypersurface} ---
the piecewise linear skeleton of an algebraic variety in the max-plus semiring --- and we
identify the exact algebraic laws controlling its complexity. Our central objects are
\emph{tropical polynomials} (pointwise maxima of affine monomials) and \emph{tropical
rational functions} (their differences). We prove that a tropical polynomial is convex,
continuous, and piecewise linear; that the pointwise maximum of two tropical polynomials is
a tropical polynomial whose monomial family is the \emph{disjoint union} of the two (so
monomial counts \emph{add}); and that their pointwise sum is a tropical polynomial whose
monomial family is the \emph{Cartesian product} of the two (so monomial counts
\emph{multiply}). We derive the ReLU identity $\max(p-q,0) = \max(p,q) - q$, which shows each
rectifying layer at most doubles the numerator monomial count. Consequences: the algebraic
degree of the boundary is bounded by $2^L$ for depth $L$, and the number of linear regions is
bounded by $2^L \prod_i w_i$ for layer widths $w_i$. We characterize the boundary as the
closed equalizer $\{x : p(x) = q(x)\}$, describe its singular locus as a
multiplicity-of-argmax condition, and outline curvature-free robustness certificates.
\end{abstract}

\section{Introduction}
Neural networks with rectified-linear activations are compositions of affine maps and
coordinatewise maxima with zero, hence piecewise linear. Tropical geometry studies the
combinatorial shadows of algebraic varieties obtained by replacing addition and multiplication
with maximum and addition. The two subjects meet at one observation: a convex piecewise linear
function is exactly a tropical polynomial, and a general ReLU-computable function is a difference
of two such --- a tropical rational function.

Our contributions: (1) structural regularity of tropical polynomials; (2) the addition law
(max adds monomial counts); (3) the multiplication law (sum multiplies monomial counts); (4) the
ReLU identity and the resulting $2^L$ degree and $2^L\prod_i w_i$ region bounds; (5) the equalizer
description and singular locus of the boundary.

\section{The tropical semiring and tropical polynomials}

The \emph{max-plus (tropical) semiring} is $(\R \cup \{-\infty\}, \oplus, \odot)$ with
$a \oplus b := \max(a,b)$ and $a \odot b := a + b$. Tropical addition is idempotent, tropical
multiplication distributes over it, $-\infty$ is the additive identity and $0$ the multiplicative
identity. A tropical monomial with coefficient $a$ and exponent vector $w$ evaluates in ordinary
arithmetic to the affine function $a + \inner{w}{x}$.

\begin{definition}[Tropical polynomial]
Let $n \in \N$ and let $\mathcal I$ be a nonempty finite index set. Given $a : \mathcal I \to \R$
and $w : \mathcal I \to \R^n$, the associated tropical polynomial is
\[ p(x) = \max_{i \in \mathcal I}\Big( a_i + \sum_{j=1}^n w_{ij}\, x_j\Big) = \max_{i\in\mathcal I}\big(a_i + \inner{w_i}{x}\big). \]
Each $m_i(x) = a_i + \inner{w_i}{x}$ is an affine monomial.
\end{definition}

\begin{definition}[Tropical rational function]
A tropical rational function is a difference $f = p \ominus q := p - q$ of two tropical polynomials.
We call $p$ the numerator and $q$ the denominator.
\end{definition}

\begin{definition}[Tropical hypersurface and variety]
The tropical hypersurface of $p$ is the set where the defining maximum is attained by at least two
monomials (the non-smooth locus). For $f = p \ominus q$, the associated variety is the equalizer
$\{x : p(x) = q(x)\} = \{x : f(x) = 0\}$.
\end{definition}

\section{Structural regularity}

Fix $n$ and a nonempty finite $\mathcal I$ with data $(a,w)$, and write
$p(x) = \max_i(a_i + \inner{w_i}{x})$.

\begin{lemma}[Monomial lower bound]
For every $x$ and $i$, $\ a_i + \inner{w_i}{x} \le p(x)$.
\end{lemma}
\begin{proof} Each element of a finite family is at most its maximum. \end{proof}

\begin{lemma}[Attainment]
For every $x$ there is $i$ with $p(x) = a_i + \inner{w_i}{x}$.
\end{lemma}
\begin{proof} A finite nonempty family attains its maximum. \end{proof}

\begin{theorem}[Convexity]
$p$ is convex on $\R^n$.
\end{theorem}
\begin{proof}
Each $m_i$ is affine, hence convex. For $\alpha,\beta \ge 0$ with $\alpha+\beta=1$ and any $i$,
$m_i(\alpha x + \beta y) = \alpha m_i(x) + \beta m_i(y) \le \alpha p(x) + \beta p(y)$ by the lower
bound lemma. Taking the maximum over $i$ on the left gives
$p(\alpha x + \beta y) \le \alpha p(x) + \beta p(y)$.
\end{proof}

\begin{theorem}[Continuity]
$p$ is continuous.
\end{theorem}
\begin{proof}
$p$ is the pointwise maximum of finitely many affine functions. For a threshold $y < p(x)$, a
maximizing monomial $m_i$ exceeds $y$ on an open neighborhood and $p \ge m_i$ there. For
$y > p(x)$, every $m_i(x) < y$, and each affine $m_i$ stays below $y$ on a neighborhood; the finite
intersection keeps $p < y$. Both one-sided order conditions hold, giving continuity.
\end{proof}

\section{The two growth laws}

Let $\mathcal I, \mathcal J$ be nonempty finite index sets with data $(a_1,w_1)$ over $\mathcal I$
and $(a_2,w_2)$ over $\mathcal J$, defining tropical polynomials $p_1, p_2$.

\begin{theorem}[Addition law]
The pointwise maximum of two tropical polynomials is a tropical polynomial whose monomial family is
the disjoint union of the two:
\[ \max\big(p_1(x), p_2(x)\big) = \max_{k \in \mathcal I \sqcup \mathcal J}\big(\tilde a_k + \inner{\tilde w_k}{x}\big), \]
where $(\tilde a,\tilde w)$ restricts to $(a_1,w_1)$ and $(a_2,w_2)$ on the two summands. Hence the
monomial count is $|\mathcal I| + |\mathcal J|$.
\end{theorem}
\begin{proof}
$(\le)$ $\max(p_1,p_2)$ equals the larger of $p_1,p_2$, attained by a monomial of the corresponding
family (attainment lemma), a monomial of the disjoint union. $(\ge)$ Every monomial of the disjoint
union is bounded above by $p_1$ or $p_2$, hence by $\max(p_1,p_2)$; the maximum over the union
preserves the bound.
\end{proof}

\begin{theorem}[Multiplication law]
The pointwise sum of two tropical polynomials is a tropical polynomial whose monomial family is the
Cartesian product of the two:
\[ p_1(x) + p_2(x) = \max_{(i,k) \in \mathcal I \times \mathcal J}\Big( (a_1(i)+a_2(k)) + \inner{w_1(i)+w_2(k)}{x}\Big). \]
Hence the monomial count is $|\mathcal I|\cdot|\mathcal J|$.
\end{theorem}
\begin{proof}
$(\le)$ Choose maximizers $i^\star, k^\star$ for $p_1(x), p_2(x)$; then $p_1(x)+p_2(x)$ equals the
$(i^\star,k^\star)$ product monomial, at most the maximum over the product. $(\ge)$ Each product
monomial is $m^{(1)}_i(x)+m^{(2)}_k(x) \le p_1(x)+p_2(x)$; the maximum preserves the bound.
\end{proof}

\section{ReLU on tropical rationals and layerwise doubling}

\begin{lemma}[ReLU identity]
For all real $p,q$, \ $\max(p-q,\,0) = \max(p,q) - q$.
\end{lemma}
\begin{proof}
If $p \ge q$, both sides equal $p-q$. If $p < q$, both sides equal $0$.
\end{proof}

\begin{corollary}[ReLU on tropical rationals]
For $f = p \ominus q$, $\ \ReLU(f) = \max(f,0) = \max(p,q) \ominus q$. By the addition law the new
numerator $\max(p,q)$ has the disjoint union of the numerator and denominator families; if $f$ has
numerator count $m$ and denominator count $d$, then $\ReLU(f)$ has numerator count
$m+d \le 2\max(m,d)$ and denominator count $d$.
\end{corollary}

\begin{corollary}[Depth $\Rightarrow$ degree $\le 2^L$]
If $m_0 = 1$ and $m_{k+1} \le 2 m_k$ for $k=0,\dots,L-1$, then $m_L \le 2^L$. Hence the algebraic
degree of the tropical hypersurface computed by a depth-$L$ network is at most $2^L$.
\end{corollary}
\begin{proof} Induction on $k$. \end{proof}

\begin{corollary}[Width $\Rightarrow$ region count $\prod w_i$]
A tropical product over $L$ factors, factor $i$ having $w_i$ monomials, has exactly
$\prod_{i=1}^L w_i$ monomials.
\end{corollary}
\begin{proof} Iterate the multiplication law: $|\prod_i \mathcal I_i| = \prod_i w_i$. \end{proof}

Combining, the number of linear regions of a depth-$L$, width-$(w_i)$ network is bounded by
$2^L \prod_i w_i$.

\section{Geometry of the decision boundary}

Let $f = p \ominus q$ be the tropical rational of a binary classifier.

\begin{proposition}[Equalizer]
$\{x : f(x)=0\} = \{x : p(x) = q(x)\}$.
\end{proposition}

\begin{proposition}[Closedness]
The decision boundary is closed, being $f^{-1}(\{0\})$ for the continuous $f = p-q$.
\end{proposition}

\begin{proposition}[Sign governed by dominant family]
Off the boundary, $\sign(f(x)) = +1$ iff $p(x) > q(x)$ and $-1$ iff $q(x) > p(x)$; the label at $x$
is determined by which tropical polynomial dominates there.
\end{proposition}

\paragraph{Singular locus.} A boundary point is smooth if the dominant maximum is attained uniquely
and singular when three or more affine pieces meet (argmax multiplicity $\ge 3$): a codimension-two
incidence condition, of the same combinatorial type as vertices of tropical curves. The number of
singular strata is bounded by $\prod_i \binom{w_i}{2}$.

\section{Algorithms}
\textbf{Tropical extraction.} Propagate $(p,q)$ layer by layer: affine layers apply the addition and
multiplication laws; ReLU layers apply $\max(p,q)\ominus q$. \textbf{Region enumeration.} Sample a
grid, evaluate $f = p-q$ by maxima over families, extract the zero level set, and flag points where
$\ge 3$ indices tie as singular. \textbf{Robustness.} At $x_0$ with margin $|f(x_0)|$, the certified
radius is $|f(x_0)|/(\|w^{(p)}_\star\| + \|w^{(q)}_\star\|)$ with dominant slopes
$w^{(p)}_\star, w^{(q)}_\star$, curvature-free by convexity.

\section{Applications and discussion}
The correspondence is exact, reducing expressivity to combinatorics of monomial families and boundary
geometry to incidence among affine pieces. Convexity removes curvature from robustness analysis. The
worst-case bounds $2^L$ and $2^L\prod_i w_i$ overcount active regions in trained networks; typical
monomial counts are an open direction.

\section{Future directions}
\begin{enumerate}
\item \textbf{Exact monomial-count recursion.} $m_{k+1} = m_k + d_k$ with $d_k$ the current
denominator count, hence $\le 2^L\prod_i w_i$, attained on an open set of weights, via the disjoint-
union mechanism of the ReLU identity.
\item \textbf{Codimension-two singular locus.} Non-smooth boundary points form a codimension-two
tropical stratum with count $\le \prod_i \binom{w_i}{2}$, a multiplicity-$\ge 3$ argmax condition.
\item \textbf{Curvature-free certified robustness.} The certified radius is the margin divided by
twice the sum of the two dominant monomial slopes, with no second-order term, because convexity forces
the local Lipschitz constant onto a single affine piece.
\end{enumerate}

\section{Conclusion}
The decision boundary of a rectified-linear classifier is a tropical hypersurface whose complexity is
governed by two exact laws: monomial counts add under rectification and multiply under composition.
These yield the degree bound $2^L$, region bound $2^L\prod_i w_i$, the closed equalizer description,
and curvature-free robustness certificates. Depth and width directly determine the algebraic
complexity of the classification frontier.

\end{document}

