from dataclasses import dataclass
from itertools import product
from typing import Tuple

Vector = Tuple[float, ...]

@dataclass(frozen=True)
class Monomial:
    coeff: float
    weight: Vector
    def value(self, x): return self.coeff + sum(w*xi for w,xi in zip(self.weight, x))

@dataclass(frozen=True)
class TP:
    monomials: Tuple[Monomial, ...]
    def value(self, x): return max(m.value(x) for m in self.monomials)
    @property
    def count(self): return len(self.monomials)

def trop_max(p, q): return TP(p.monomials + q.monomials)
def trop_add(p, q):
    return TP(tuple(Monomial(a.coeff+b.coeff, tuple(x+y for x,y in zip(a.weight,b.weight)))
                    for a,b in product(p.monomials, q.monomials)))

p = TP((Monomial(0.0,(1.0,0.0)), Monomial(1.0,(0.0,1.0))))
q = TP((Monomial(-0.5,(0.0,-1.0)), Monomial(0.2,(-1.0,0.0)), Monomial(0.0,(1.0,1.0))))
print("addition law:      ", trop_max(p,q).count, "=", p.count, "+", q.count)
print("multiplication law:", trop_add(p,q).count, "=", p.count, "*", q.count)
for x in ((0.3,-0.7),(1.1,2.0),(-1.5,0.4)):
    assert abs(max(p.value(x),q.value(x)) - trop_max(p,q).value(x)) < 1e-9
    assert abs(p.value(x)+q.value(x) - trop_add(p,q).value(x)) < 1e-9
print("pointwise identities verified")

def relu(t): return max(t, 0.0)
max_err = 0.0
for p in (-3.0,-1.2,0.0,0.7,4.5):
    for q in (-2.0,0.0,1.3,3.0):
        max_err = max(max_err, abs(relu(p-q) - (max(p,q)-q)))
print("max |ReLU(p-q) - (max(p,q)-q)| =", max_err)

def doubling_bound(L):
    m = 1
    for _ in range(L): m *= 2
    return m
for L in range(6):
    print(f"depth {L}: degree bound 2^L = {doubling_bound(L)}")

