        num_families  <- [ N if w_j >= 0 else D  for each input j ]
        den_families  <- [ D if w_j >= 0 else N  for each input j ]
        N' <- { sum over one monomial per input family, coeffs/weights added, plus c }
        D' <- { same over den_families }
    (N, D) <- (N', D')
    # ReLU layer: addition (max) law via ReLU identity
    N <- N (disjoint-union) D        # numerator count -> |N| + |D|
    D <- D                            # denominator unchanged
return f = (N, D)

