from __future__ import annotations
from dataclasses import dataclass
from itertools import product
from typing import List, Tuple

Vector = Tuple[float, ...]

@dataclass(frozen=True)
class Monomial:
    coeff: float
    weight: Vector

@dataclass(frozen=True)
class TropicalRational:
    """f = p - q, numerator and denominator monomial families."""
    numerator: Tuple[Monomial, ...]
    denominator: Tuple[Monomial, ...]

def affine_layer(f: TropicalRational, W: List[List[float]], b: List[float]) -> TropicalRational:
    """Apply an affine map row-wise. For a scalar output row (w, c):
    combine numerator/denominator via the tropical multiplication (sum) law,
    routing positive/negative weights to numerator/denominator accordingly."""
    # Single-output illustration: y = c + sum_k w_k * f_k.
    num: List[Monomial] = []
    den: List[Monomial] = []
    w, c = W[0], b[0]
    # positive weights keep orientation, negative weights swap num/den (tropical minus)
    fams_num = [f.numerator] * 0
    # Cartesian product over channels realises the multiplication law.
    num_families = [f.numerator if wk >= 0 else f.denominator for wk in w]
    den_families = [f.denominator if wk >= 0 else f.numerator for wk in w]
    for combo in product(*num_families):
        coeff = c + sum(abs(wk) * m.coeff for wk, m in zip(w, combo))
        weight = tuple(sum(abs(wk) * m.weight[j] for wk, m in zip(w, combo))
                       for j in range(len(combo[0].weight)))
        num.append(Monomial(coeff, weight))
    for combo in product(*den_families):
        coeff = sum(abs(wk) * m.coeff for wk, m in zip(w, combo))
        weight = tuple(sum(abs(wk) * m.weight[j] for wk, m in zip(w, combo))
                       for j in range(len(combo[0].weight)))
        den.append(Monomial(coeff, weight))
    return TropicalRational(tuple(num), tuple(den))

def relu_layer(f: TropicalRational) -> TropicalRational:
    """ReLU identity: ReLU(p - q) = max(p, q) - q.
    New numerator is the DISJOINT UNION of numerator and denominator families."""
    new_numerator = f.numerator + f.denominator
    return TropicalRational(new_numerator, f.denominator)

def numerator_count(f: TropicalRational) -> int:
    return len(f.numerator)

