from __future__ import annotations
from typing import List, Tuple

Vector = Tuple[float, ...]

def l2(v: Vector) -> float:
    return sum(c * c for c in v) ** 0.5

def certified_radius(num: List[Tuple[float, Vector]],
                     den: List[Tuple[float, Vector]],
                     x0: Vector, tol: float = 1e-9) -> float:
    """Curvature-free certified robustness radius:
        margin / (||dominant numerator slope|| + ||dominant denominator slope||).
    Valid because each tropical polynomial is convex, so the local Lipschitz
    constant is realized by a single active affine piece."""
    def evalf(mons: List[Tuple[float, Vector]]) -> float:
        return max(a + sum(w * xi for w, xi in zip(wv, x0)) for a, wv in mons)
    def dominant_weight(mons: List[Tuple[float, Vector]]) -> Vector:
        vals = [a + sum(w * xi for w, xi in zip(wv, x0)) for a, wv in mons]
        best = max(vals)
        for (a, wv), v in zip(mons, vals):
            if abs(v - best) <= tol:
                return wv
        return mons[0][1]
    margin = abs(evalf(num) - evalf(den))
    denom = l2(dominant_weight(num)) + l2(dominant_weight(den))
    return margin / denom if denom > 0 else float("inf")
